from PIL import Image
import numpy as np
im=np.array(Image.open('first_frame.png')).astype(float)
R,G,B=im.transpose(2,0,1)
# orange ranges
for y in range(44,68):
 om=(R[y]>125)&(R[y]>G[y]*1.25)&(G[y]>B[y]*1.12)
 xs=np.where(om)[0]; xs=xs[(xs>100)&(xs<160)]
 runs=[]
 for x in xs:
  if not runs or x>runs[-1][-1]+1:runs.append([x])
  else:runs[-1].append(x)
 print('o',y,[(r[0],r[-1]) for r in runs if len(r)>=1])
print('brown rows x ranges based saturation/dark')
for y in range(43,68):
 # brown mask: dark reddish; exclude pipe x<110
 bm=(R[y]<115)&(R[y]>35)&(R[y]>G[y]*1.2)&(G[y]>B[y]*1.05)
 xs=np.where(bm)[0]; xs=xs[(xs>=109)&(xs<135)]
 runs=[]
 for x in xs:
  if not runs or x>runs[-1][-1]+1:runs.append([x])
  else:runs[-1].append(x)
 print(y,[(r[0],r[-1]) for r in runs if len(r)>=1])
